scripts.build:
rm -rf dist && mkdir -p dist/server dist/.openai dist/_appgen_meta && cp -R outputs/. dist/ && cp .openai/hosting.json dist/.openai/hosting.json && if [ ! -f dist/index.html ]; then cat > dist/index.html <<'EOF'
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>ParTime</title>
    <meta name="description" content="ParTime marketplace site" />
    <link rel="stylesheet" href="/styles.css" />
  </head>
  <body>
    <div id="app"></div>
    <script src="/app.js" defer></script>
  </body>
</html>
EOF
fi
cat > dist/server/index.js <<'EOF'
export default {
  async fetch(request, env) {
    if (env && env.ASSETS && typeof env.ASSETS.fetch === 'function') {
      const url = new URL(request.url);
      const wantsFile = url.pathname.includes('.') && !url.pathname.endsWith('/');
      const assetRequest = async (pathname) => {
        const assetUrl = new URL(request.url);
        assetUrl.pathname = pathname;
        return env.ASSETS.fetch(new Request(assetUrl, request));
      };

      const primary = await assetRequest(url.pathname === '/' ? '/index.html' : url.pathname);
      if (primary.status !== 404) return primary;

      if (!wantsFile) {
        const fallback = await assetRequest('/index.html');
        if (fallback.status !== 404) return fallback;
      }

      return primary;
    }
    return new Response('', { status: 204 });
  }
};
EOF
printf '{}\n' > dist/_appgen_meta/appgarden.json
